-- PINTURAS JAM / Chat 4: caja, arqueo y cierre. Aplicar sólo después de revisar en staging.
create table if not exists public.jam_cash_sessions (
 id uuid primary key default gen_random_uuid(), business_id uuid not null, opened_by uuid not null,
 opened_at timestamptz not null default now(), opening_amount numeric(18,6) not null check(opening_amount>=0),
 currency text not null check(currency in ('VES','USD')), status text not null default 'open' check(status in ('open','closed')),
 closed_by uuid, closed_at timestamptz, expected_amount numeric(18,6), counted_amount numeric(18,6), difference numeric(18,6), notes text,
 created_at timestamptz not null default now()
);
create unique index if not exists jam_cash_one_open_per_currency on public.jam_cash_sessions(business_id,currency) where status='open';
create table if not exists public.jam_cash_movements (
 id uuid primary key default gen_random_uuid(), business_id uuid not null, session_id uuid not null references public.jam_cash_sessions(id),
 movement_type text not null check(movement_type in ('opening','income','expense','closing_adjustment')),
 amount numeric(18,6) not null check(amount>0), currency text not null check(currency in ('VES','USD')),
 description text not null, reference text, source_type text, source_id uuid, idempotency_key text not null,
 actor_id uuid not null, created_at timestamptz not null default now(), unique(business_id,idempotency_key)
);
create index if not exists jam_cash_movements_session_idx on public.jam_cash_movements(business_id,session_id,created_at);
alter table public.jam_cash_sessions enable row level security;
alter table public.jam_cash_movements enable row level security;
drop policy if exists jam_cash_sessions_read on public.jam_cash_sessions;
create policy jam_cash_sessions_read on public.jam_cash_sessions for select to authenticated using (business_id in (select business_id from public.jam_user_access where user_id=auth.uid() and active));
drop policy if exists jam_cash_movements_read on public.jam_cash_movements;
create policy jam_cash_movements_read on public.jam_cash_movements for select to authenticated using (business_id in (select business_id from public.jam_user_access where user_id=auth.uid() and active));
create or replace function public.jam_cash_require_role(p_write boolean default false) returns uuid language plpgsql stable security definer set search_path=public,auth as $$
declare b uuid; r text; begin select business_id,role into b,r from public.jam_user_access where user_id=auth.uid() and active limit 1; if b is null then raise exception 'Usuario sin acceso al negocio' using errcode='42501'; end if; if p_write and r not in ('owner','admin','sales') then raise exception 'Permiso de caja requerido' using errcode='42501'; end if; return b; end $$;
create or replace function public.jam_cash_session_open(p_amount numeric,p_currency text,p_notes text default null) returns jsonb language plpgsql security definer set search_path=public,auth as $$
declare b uuid; s public.jam_cash_sessions; begin b:=public.jam_cash_require_role(true); if p_amount<0 or p_currency not in ('VES','USD') then raise exception 'Monto o moneda inválidos'; end if; insert into public.jam_cash_sessions(business_id,opened_by,opening_amount,currency,notes) values(b,auth.uid(),p_amount,p_currency,nullif(trim(p_notes),'')) returning * into s; if p_amount>0 then insert into public.jam_cash_movements(business_id,session_id,movement_type,amount,currency,description,idempotency_key,actor_id) values(b,s.id,'income',p_amount,p_currency,'Fondo de apertura','open:'||s.id,auth.uid()); end if; return to_jsonb(s); end $$;
create or replace function public.jam_cash_movement_add(p_session uuid,p_type text,p_amount numeric,p_description text,p_reference text,p_key text) returns jsonb language plpgsql security definer set search_path=public,auth as $$
declare b uuid; s public.jam_cash_sessions; m public.jam_cash_movements; begin b:=public.jam_cash_require_role(true); if p_type not in ('income','expense') or p_amount<=0 or nullif(trim(p_description),'') is null or nullif(trim(p_key),'') is null then raise exception 'Datos del movimiento inválidos'; end if; select * into m from public.jam_cash_movements where business_id=b and idempotency_key=trim(p_key); if found then return to_jsonb(m); end if; select * into s from public.jam_cash_sessions where id=p_session and business_id=b and status='open' for update; if not found then raise exception 'Caja no existe o está cerrada'; end if; insert into public.jam_cash_movements(business_id,session_id,movement_type,amount,currency,description,reference,idempotency_key,actor_id) values(b,s.id,p_type,p_amount,s.currency,trim(p_description),nullif(trim(p_reference),''),trim(p_key),auth.uid()) returning * into m; return to_jsonb(m); end $$;
create or replace function public.jam_cash_session_summary(p_session uuid) returns jsonb language plpgsql stable security definer set search_path=public,auth as $$
declare b uuid; s public.jam_cash_sessions; inc numeric; exp numeric; begin b:=public.jam_cash_require_role(false); select * into s from public.jam_cash_sessions where id=p_session and business_id=b; if not found then raise exception 'Caja no encontrada'; end if; select coalesce(sum(amount) filter(where movement_type='income'),0),coalesce(sum(amount) filter(where movement_type='expense'),0) into inc,exp from public.jam_cash_movements where business_id=b and session_id=s.id; return jsonb_build_object('session',to_jsonb(s),'income',inc,'expense',exp,'expected',s.opening_amount+inc-exp); end $$;
create or replace function public.jam_cash_session_close(p_session uuid,p_counted numeric,p_notes text default null) returns jsonb language plpgsql security definer set search_path=public,auth as $$
declare b uuid; s public.jam_cash_sessions; inc numeric; exp numeric; expected numeric; begin b:=public.jam_cash_require_role(true); if p_counted<0 then raise exception 'El arqueo no puede ser negativo'; end if; select * into s from public.jam_cash_sessions where id=p_session and business_id=b and status='open' for update; if not found then raise exception 'Caja inexistente o ya cerrada'; end if; select coalesce(sum(amount) filter(where movement_type='income'),0),coalesce(sum(amount) filter(where movement_type='expense'),0) into inc,exp from public.jam_cash_movements where business_id=b and session_id=s.id; expected:=s.opening_amount+inc-exp; update public.jam_cash_sessions set status='closed',closed_by=auth.uid(),closed_at=now(),expected_amount=expected,counted_amount=p_counted,difference=p_counted-expected,notes=concat_ws(E'\n',notes,nullif(trim(p_notes),'')) where id=s.id returning * into s; return jsonb_build_object('session',to_jsonb(s),'income',inc,'expense',exp,'expected',expected,'counted',p_counted,'difference',p_counted-expected); end $$;
-- Consume eventos comerciales dentro de caja: mismo negocio/moneda y sesión abierta. Idempotente.
create or replace function public.jam_cash_events_consume(p_session uuid,p_limit integer default 100) returns jsonb language plpgsql security definer set search_path=public,auth as $$
declare b uuid; s public.jam_cash_sessions; e public.jam_cash_events; n integer:=0; amt numeric; typ text; begin b:=public.jam_cash_require_role(true); select * into s from public.jam_cash_sessions where id=p_session and business_id=b and status='open' for update; if not found then raise exception 'Abra una caja antes de sincronizar eventos'; end if; for e in select * from public.jam_cash_events where business_id=b and consumed_at is null and currency=s.currency order by created_at for update skip locked limit greatest(1,least(coalesce(p_limit,100),500)) loop amt:=case when e.applied_rate is not null and e.currency='VES' then e.amount else e.amount end; typ:=case when e.event_type in ('supplier_payment','sale_change') then 'expense' else 'income' end; insert into public.jam_cash_movements(business_id,session_id,movement_type,amount,currency,description,reference,source_type,source_id,idempotency_key,actor_id) values(b,s.id,typ,amt,e.currency,e.event_type,e.source_id::text,e.source_type,e.source_id,'event:'||e.id,auth.uid()) on conflict(business_id,idempotency_key) do nothing; update public.jam_cash_events set consumed_at=now(),consumer_reference='cash:'||s.id where id=e.id and business_id=b and consumed_at is null; n:=n+1; end loop; return jsonb_build_object('consumed',n,'sessionId',s.id,'currency',s.currency); end $$;
revoke all on function public.jam_cash_require_role(boolean) from public,anon;
revoke all on function public.jam_cash_session_open(numeric,text,text) from public,anon;
revoke all on function public.jam_cash_movement_add(uuid,text,numeric,text,text,text) from public,anon;
revoke all on function public.jam_cash_session_summary(uuid) from public,anon;
revoke all on function public.jam_cash_session_close(uuid,numeric,text) from public,anon;
revoke all on function public.jam_cash_events_consume(uuid,integer) from public,anon;
grant execute on function public.jam_cash_session_open(numeric,text,text),public.jam_cash_movement_add(uuid,text,numeric,text,text,text),public.jam_cash_session_summary(uuid),public.jam_cash_session_close(uuid,numeric,text),public.jam_cash_events_consume(uuid,integer) to authenticated;
